  authors=["Réka Lukács","Marcel Guillong","János Szepesi","Dawid Szymanowski","Maxim Portnyagin","Sándor Józsa","Olivier Bachmann","Maurizio Petrelli","Samuel Müller","David Schiller","László Fodor","Cyril Chelle-Michou","Szabolcs Harangi"],
