  title="Tracing widespread Early Miocene ignimbrite eruptions and petrogenesis at the onset of the Carpathian-Pannonian Region silicic volcanism",
  authors=["Mihovil Brlek","Simon Tapster","Julie Schindlbeck-Belo","Sean P. Gaynor","Steffen Kutterolf","Folkmar Hauff","Svetoslav V. Georgiev","Nina Trinajstić","Sanja Šuica","Vlatko Brčić","Kuo-Lung Wang","Hao-Yang Lee","Christoph Beier","Adam B. Abersteiner","Ivan Mišur","Irena Peytcheva","Duje Kukoč","Bianka Németh","Mirka Trajanova","Dražen Balen","Marcel Guillong","Dawid Szymanowski","Réka Lukács"],
